-- Verify bytes and the actual runtime before loading a local unsigned candidate.
SELECT CASE WHEN version() = 'v2.0.0' THEN true ELSE error('DuckDB 2.0.0 required') END AS runtime_ok;
SELECT CASE WHEN sha256(content) = 'c5f36a0f99213b570c1fe862561f3bb8882f40936c0afe6565f46ceca1878d48'
            THEN true ELSE error('Extension hash mismatch') END AS artifact_ok
FROM read_blob('/Users/kevintruong/project/SpurCode/.spur/artifacts/notebook-symbol-uplift-native/spur_graph.duckdb_extension');
LOAD '/Users/kevintruong/project/SpurCode/.spur/artifacts/notebook-symbol-uplift-native/spur_graph.duckdb_extension';
SELECT version() AS runtime, (spur_graph_info()).duckdb_api_version AS extension_api,
       (spur_graph_info()).extractor_id AS extractor_id;
